export type AutoPartSeed = {
  slug: string;
  nameEn: string;
  nameRu: string;
  categorySlug: string;
  categoryEn: string;
  categoryRu: string;
  descriptionEn: string;
  descriptionRu: string;
  functionEn: string;
  functionRu: string;
  replacementEn: string;
  replacementRu: string;
};

const CATS: Record<string, { slug: string; en: string; ru: string }> = {
  engine: { slug: 'engine', en: 'Engine', ru: 'Двигатель' },
  transmission: { slug: 'transmission', en: 'Transmission', ru: 'Трансмиссия' },
  brakes: { slug: 'brakes', en: 'Brakes', ru: 'Тормоза' },
  suspension: { slug: 'suspension', en: 'Suspension', ru: 'Подвеска' },
  steering: { slug: 'steering', en: 'Steering', ru: 'Рулевое управление' },
  electrical: { slug: 'electrical', en: 'Electrical', ru: 'Электрика' },
  cooling: { slug: 'cooling', en: 'Cooling', ru: 'Охлаждение' },
  exhaust: { slug: 'exhaust', en: 'Exhaust', ru: 'Выхлопная система' },
  fuel: { slug: 'fuel', en: 'Fuel system', ru: 'Топливная система' },
  filters: { slug: 'filters', en: 'Filters & fluids', ru: 'Фильтры и жидкости' },
  hvac: { slug: 'hvac', en: 'Climate control', ru: 'Климат-контроль' },
  lighting: { slug: 'lighting', en: 'Lighting', ru: 'Освещение' },
  interior: { slug: 'interior', en: 'Interior', ru: 'Салон' },
  exterior: { slug: 'exterior', en: 'Body & exterior', ru: 'Кузов и экстерьер' },
  wheels: { slug: 'wheels', en: 'Wheels & tires', ru: 'Колёса и шины' },
  safety: { slug: 'safety', en: 'Safety', ru: 'Безопасность' },
};

type Row = [string, string, string, string, string, string, string, string, string];

function expand(cat: string, rows: Row[]): AutoPartSeed[] {
  const c = CATS[cat];
  return rows.map(([slug, nameEn, nameRu, descriptionEn, descriptionRu, functionEn, functionRu, replacementEn, replacementRu]) => ({
    slug,
    nameEn,
    nameRu,
    categorySlug: c.slug,
    categoryEn: c.en,
    categoryRu: c.ru,
    descriptionEn,
    descriptionRu,
    functionEn,
    functionRu,
    replacementEn,
    replacementRu,
  }));
}

